(()=>{'use strict';const $=id=>document.getElementById(id);let running=false,progress=0,speed=1,last=0;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const fit=()=>document.documentElement.style.setProperty('--scale',Math.min(innerWidth/1920,innerHeight/1080));fit();addEventListener('resize',fit);const clock=()=>{$('clock').textContent=new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date());};clock();setInterval(clock,1000);const panel=(t,en,body,c='')=>`<section class="panel ${c}"><div class="panel-title"><h2>${t}</h2><span>${en}</span></div><div class="route-panel-body">${body}</div></section>`;
$('suite-main').innerHTML=`<div class="route-layout"><aside class="route-sidebar">${panel('车辆信息','VEHICLE INFORMATION',`<div class="route-vehicle"><img src="./assets/energy/iso-truck.svg" alt="重卡"><div><span>车牌号</span><h2>晋J-0186D</h2><b>待装载</b></div></div><dl class="route-facts"><div><dt>所属公司</dt><dd>山西科达自控股份有限公司</dd></div><div><dt>司机</dt><dd>李民桥</dd></div><div><dt>联系电话</dt><dd>132****3721</dd></div></dl>`)}${panel('回放设置','PLAYBACK SETTINGS',`<label class="route-field">轨迹日期<input id="route-date" type="date" value="2024-03-07"></label><label class="route-field">播放速度<select id="route-speed"><option value="1">1X / 标准速度</option><option value="8">8X / 快速回放</option><option value="32">32X / 快速定位</option></select></label><button class="suite-button route-reset" id="route-reset">回到轨迹起点 ↶</button><p class="route-note">当前地图与轨迹为演示示意，用于展示历史轨迹回放。</p>`)}${panel('回放状态','PLAYBACK STATUS',`<div class="play-state"><span id="route-state">已暂停</span><i class="live-dot"></i></div><div class="route-readings"><div><span>播放进度</span><b id="route-percent">0<small>%</small></b></div><div><span>当前速度</span><b id="route-rate">1<small>X</small></b></div></div><div class="route-current"><span>当前示意节点</span><b id="route-node">01 / 起点</b></div>`,'route-state-panel')}</aside><div class="route-content"><div class="suite-toolbar"><div><h2>车辆历史轨迹</h2><small>晋J-0186D / 2024-03-07</small></div><span class="route-demo-label">演示轨迹 / 非实时位置</span></div><section class="route-map"><img class="route-basemap" src="./assets/energy/regional-scene.svg" alt="区域道路示意底图"><div class="map-caption"><b>车辆行驶路径</b><span>VEHICLE MOVEMENT / PLAYBACK</span></div><svg id="route-map-svg" viewBox="0 0 1200 600" preserveAspectRatio="xMidYMid meet" role="img" aria-label="车辆示意轨迹：从起点到终点共五个节点"><defs><linearGradient id="route-ink"><stop stop-color="#4b94b1"/><stop offset="1" stop-color="#a9dae4"/></linearGradient></defs><path d="M150 450L380 430 560 250 840 230 1040 130" stroke="#020e19" stroke-width="17" fill="none"/><path d="M150 450L380 430 560 250 840 230 1040 130" stroke="#31516a" stroke-width="7" fill="none"/><path id="route-progress-path" d="M150 450L380 430 560 250 840 230 1040 130" stroke="url(#route-ink)" stroke-width="4" fill="none"/>${[[150,450],[380,430],[560,250],[840,230],[1040,130]].map(([x,y],i)=>`<g class="route-point"><circle cx="${x}" cy="${y}" r="9" fill="#0c2b40" stroke="#83bfd2" stroke-width="1.4"/><circle cx="${x}" cy="${y}" r="3" fill="#8cc6d6"/><rect x="${x-49}" y="${y+23}" width="98" height="30" fill="#0d2c40" stroke="#496e8577"/><text x="${x}" y="${y+43}" text-anchor="middle">${i===0?'起点':i===4?'终点':'示意节点 0'+(i+1)}</text></g>`).join('')}<g id="route-moving-truck"><ellipse cx="0" cy="7" rx="32" ry="11" fill="#000" opacity=".4"/><image href="./assets/energy/iso-truck.svg" x="-40" y="-68" width="80" height="80"/></g></svg><div class="route-map-legend"><span><i></i>示意轨迹</span><span><i></i>当前播放位置</span><small id="route-map-note">地图与位置为演示示意，未接入真实历史数据</small></div><div class="map-compass"><span>N</span><i></i></div></section><section class="route-control-panel panel"><div class="route-control-top"><div><button class="suite-button primary" id="route-play">播放轨迹 ▶</button><button class="suite-button" id="route-restart">重新播放 ↶</button></div><span id="route-control-status">已暂停 / 1X</span></div><div class="route-progress"><span>起点</span><input id="route-range" type="range" min="0" max="100" value="0" step=".1" aria-label="轨迹回放进度"><span>终点</span></div><div class="route-timeline">${['起点','节点 02','节点 03','节点 04','终点'].map((l,i)=>`<button type="button" data-route-point="${i}"><i></i><span>0${i+1}</span><b>${l}</b></button>`).join('')}</div></section></div></div>`;
const points=[[150,450],[380,430],[560,250],[840,230],[1040,130]];const lengths=points.slice(1).map((p,i)=>Math.hypot(p[0]-points[i][0],p[1]-points[i][1]));const totalLength=lengths.reduce((a,b)=>a+b,0);const positions=[0,25,50,75,100];function update(){const scaled=progress/25,i=Math.min(3,Math.floor(scaled)),t=scaled-i;const x=points[i][0]+(points[i+1][0]-points[i][0])*t,y=points[i][1]+(points[i+1][1]-points[i][1])*t;$('route-moving-truck').setAttribute('transform',`translate(${x} ${y})`);$('route-range').value=progress;$('route-percent').innerHTML=Math.round(progress)+'<small>%</small>';$('route-rate').innerHTML=speed+'<small>X</small>';$('route-node').textContent=progress>=100?'05 / 终点':String(i+1).padStart(2,'0')+' / '+(i===0?'起点':'示意节点');const status=progress>=100?'回放完成':running?'正在回放':'已暂停';$('route-state').textContent=status;$('route-control-status').textContent=status+' / '+speed+'X';$('route-play').textContent=running?'暂停轨迹 Ⅱ':'播放轨迹 ▶';$('pause').textContent=running?'暂停演示':'播放演示';$('route-play').setAttribute('aria-pressed',String(running));document.querySelectorAll('[data-route-point]').forEach((b,j)=>{b.classList.toggle('reached',progress>=positions[j]);b.setAttribute('aria-current',Math.abs(progress-positions[j])<.1?'step':'false');});const path=$('route-progress-path');const travelled=lengths.slice(0,i).reduce((a,b)=>a+b,0)+lengths[i]*t;path.style.strokeDasharray=totalLength;path.style.strokeDashoffset=totalLength-travelled;}
function toggle(){if(progress>=100)progress=0;running=!running;last=0;update();}$('route-play').onclick=toggle;$('pause').onclick=toggle;$('route-speed').onchange=e=>{speed=Number(e.target.value);update();};$('route-range').oninput=e=>{progress=Number(e.target.value);update();};$('route-reset').onclick=()=>{running=false;progress=0;last=0;update();};$('route-restart').onclick=()=>{progress=0;running=!reduced;last=0;update();};document.querySelectorAll('[data-route-point]').forEach(b=>b.onclick=()=>{progress=positions[Number(b.dataset.routePoint)];running=false;last=0;update();});$('route-date').onchange=()=>{running=false;progress=0;last=0;$('route-map-note').textContent='所选日期 '+$('route-date').value+'：未接入历史数据，当前保留示意路线。';document.querySelector('.suite-toolbar small').textContent='晋J-0186D / '+$('route-date').value;update();};$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{const t=$('toast');t.textContent='请在独立页面中使用浏览器全屏。';t.classList.add('visible');setTimeout(()=>t.classList.remove('visible'),3000);}};
setInterval(()=>{if(!running||document.hidden){last=0;return;}const now=Date.now();const delta=last?Math.min((now-last)/1000,.5):.1;last=now;progress=Math.min(100,progress+delta*speed*1.25);if(progress>=100)running=false;update();},100);update();})();
